def list_stats(nums):
    largest = nums[0]
    smallest = nums[0]
    seen = set()
    dups = set()
    for x in nums:
        if x > largest:
            largest = x
        if x < smallest:
            smallest = x
        if x in seen:
            dups.add(x)
        seen.add(x)
    return (largest, smallest, sorted(dups))

